def get_interpretation(scale_id, score, scale_data):
    """Get appropriate interpretation based on test and score"""
    if scale_id not in INTERPRETATIONS:
        return "Συμβουλευτείτε έναν ειδικό για την ερμηνεία των αποτελεσμάτων σας."
    
    interp = INTERPRETATIONS[scale_id]
    
    # Different tests have different interpretation logic
    if scale_id == "PHQ-9":
        if score < 5:
            return interp["minimal"]
        elif score < 10:
            return interp["mild"]
        elif score < 15:
            return interp["moderate"]
        else:
            return interp["severe"]
    elif scale_id == "GAD-7":
        if score < 5:
            return interp["minimal"]
        elif score < 10:
            return interp["mild"]
        elif score < 15:
            return interp["moderate"]
        else:
            return interp["severe"]
    elif scale_id == "PQ-B":
        threshold = scale_data.get("threshold", 6)
        if score < threshold:
            return interp["low"]
        else:
            return interp["high"]
    elif scale_id in ["PID-5-BF", "PID-5"]:
        return interp["interpretation"]
    elif scale_id == "MSI-BPD":
        threshold = scale_data.get("threshold", 7)
        if score < threshold:
            return interp["low"]
        else:
            return interp["high"]
    
    return "Συμβουλευτείτε έναν ειδικό για την ερμηνεία των αποτελεσμάτων σας."
